template <bool B>
inline bool VerifyCommandBody(::flatbuffers::VerifierTemplate<B> &verifier, const void *obj, CommandBody type) {
  switch (type) {
    case CommandBody::NONE: {
      return true;
    }
    case CommandBody::NewWorld: {
      auto ptr = reinterpret_cast<const tce::wire::NewWorld *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case CommandBody::SaveWorld: {
      auto ptr = reinterpret_cast<const tce::wire::SaveWorld *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case CommandBody::LoadWorld: {
      auto ptr = reinterpret_cast<const tce::wire::LoadWorld *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case CommandBody::SetClock: {
      auto ptr = reinterpret_cast<const tce::wire::SetClock *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case CommandBody::CancelTask: {
      auto ptr = reinterpret_cast<const tce::wire::CancelTask *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case CommandBody::RecoverWorld: {
      auto ptr = reinterpret_cast<const tce::wire::RecoverWorld *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case CommandBody::SpawnFamily: {
      auto ptr = reinterpret_cast<const tce::wire::SpawnFamily *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case CommandBody::RunUntil: {
      auto ptr = reinterpret_cast<const tce::wire::RunUntil *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case CommandBody::IntroduceTechnique: {
      auto ptr = reinterpret_cast<const tce::wire::IntroduceTechnique *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case CommandBody::PlaceDeposit: {
      auto ptr = reinterpret_cast<const tce::wire::PlaceDeposit *>(obj);
      return verifier.VerifyTable(ptr);
    }
    default: return true;
  }
}

template <bool B>
inline bool VerifyCommandBodyVector(::flatbuffers::VerifierTemplate<B> &verifier, const ::flatbuffers::Vector<::flatbuffers::Offset<void>> *values, const ::flatbuffers::Vector<CommandBody> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (::flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyCommandBody(
        verifier,  values->Get(i), types->GetEnum<CommandBody>(i))) {
      return false;
    }
  }
  return true;
}

